def permute(s):
    if len(s) <= 1:
        return [s]
    result = []
    for i in range(len(s)):
        # swap s[0] and s[i]
        s_list = list(s)
        s_list[0], s_list[i] = s_list[i], s_list[0]
        # permute the rest
        for p in permute(''.join(s_list[1:])):
            result.append(s_list[0] + p)
    return result

def max_Product(arr):
    arr.sort()
    # Two possible candidates for max product
    candidate1 = (arr[-2], arr[-1])  # two largest
    candidate2 = (arr[0], arr[1])    # two smallest (possibly negative)

    if candidate1[0] * candidate1[1] >= candidate2[0] * candidate2[1]:
        return candidate1
    else:
        return candidate2

def breakSum(n, memo=None):
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]

    # Recursively compute for the three parts
    parts_sum = breakSum(n // 2, memo) + breakSum(n // 3, memo) + breakSum(n // 4, memo)

    # Take the maximum of n and the sum of parts
    result = max(n, parts_sum)
    memo[n] = result
    return result

